-- Where the statement stands among its person's statements: a person's statements are in the order of seq, then id,
-- and the last one is the person's last statement. Statements that follow a person merged into another are placed
-- before that person's own, so the receiving person's last statement stays theirs.
ALTER TABLE statement ADD COLUMN seq BIGINT;
UPDATE statement SET seq = id;
ALTER TABLE statement ALTER COLUMN seq SET NOT NULL;
CREATE INDEX statement_person_seq ON statement (person_id, seq, id);
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** Each person's statement summary on the sheet, by person id; a person with none is missing. */
    public Map<Long, StatementSummary> summaries(String sheetId) {
        Map<Long, StatementSummary> by = new HashMap<>();
        for (Statement s : statements.findBySheetIdOrderBySeqAscIdAsc(sheetId)) {
            by.put(s.getPersonId(), by.getOrDefault(s.getPersonId(), StatementSummary.NONE).then(s));
        }
        return by;
    }

    public StatementSummary summary(String sheetId, Long personId) {
        StatementSummary summary = StatementSummary.NONE;
        for (Statement s : statements.findBySheetIdAndPersonIdOrderBySeqAscIdAsc(sheetId, personId)) {
            summary = summary.then(s);
        }
        return summary;
    }

